+    private readonly PaymentGateway _gateway;
+
+    public PaymentGatewayTests()
+    {
+        _gateway = new PaymentGateway();
+    }
+
+    // ── ChargeAsync ─────────────────────────────────────────────────
+
+    [TestMethod]
+    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccessWithChargeId()
+    {
+        var result = await _gateway.ChargeAsync("tok_valid_visa", 49.99m);
+
+        Assert.IsNotNull(result);
+        Assert.IsTrue(result.Success);
+        Assert.IsNotNull(result.ChargeId);
+        Assert.AreNotEqual(string.Empty, result.ChargeId);
+    }
+
+    [TestMethod]
+    public async Task ChargeAsync_NullToken_ThrowsArgumentNullException()
+    {
+        var ex = await Assert.ThrowsExactlyAsync<ArgumentNullException>(
+            async () => await _gateway.ChargeAsync(null!, 10m));
+
+        Assert.AreEqual("cardToken", ex.ParamName);
+    }
+
+    [TestMethod]
+    public async Task ChargeAsync_EmptyToken_ThrowsArgumentException()
+    {
+        await Assert.ThrowsExactlyAsync<ArgumentException>(
+            async () => await _gateway.ChargeAsync(string.Empty, 10m));
+    }
+
+    [TestMethod]
+    [DataRow(0)]
+    [DataRow(-1)]
+    [DataRow(-100.50)]
+    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRangeException(double amount)
+    {
+        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
+            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
+    }
+
+    [TestMethod]
+    public async Task ChargeAsync_LargeAmount_ReturnsSuccess()
+    {
+        var result = await _gateway.ChargeAsync("tok_valid_visa", 9999.99m);
+
+        Assert.IsNotNull(result);
+        Assert.IsTrue(result.Success);
+    }
+
+    [TestMethod]
+    public async Task ChargeAsync_MinimumAmount_ReturnsSuccess()
+    {
+        var result = await _gateway.ChargeAsync("tok_valid_visa", 0.01m);
+
+        Assert.IsNotNull(result);
+        Assert.IsTrue(result.Success);
+    }
+
+    [TestMethod]
+    public async Task ChargeAsync_DeclinedCard_ReturnsFailure()
+    {
+        var result = await _gateway.ChargeAsync("tok_declined", 50m);
+
+        Assert.IsNotNull(result);
+        Assert.IsFalse(result.Success);
+    }
+
+    [TestMethod]
+    public async Task ChargeAsync_TwoCharges_ReturnDistinctChargeIds()
+    {
+        var first = await _gateway.ChargeAsync("tok_valid_visa", 10m);
+        var second = await _gateway.ChargeAsync("tok_valid_visa", 20m);
+
+        Assert.AreNotEqual(first.ChargeId, second.ChargeId);
+    }
+
+    // ── RefundAsync ─────────────────────────────────────────────────
+
+    [TestMethod]
+    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
+    {
+        var charge = await _gateway.ChargeAsync("tok_valid_visa", 25m);
+        var refund = await _gateway.RefundAsync(charge.ChargeId);
+
+        Assert.IsNotNull(refund);
+        Assert.IsTrue(refund.Success);
+        Assert.IsNotNull(refund.RefundId);
+        Assert.AreNotEqual(string.Empty, refund.RefundId);
+    }
+
+    [TestMethod]
+    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
+    {
+        var ex = await Assert.ThrowsExactlyAsync<ArgumentNullException>(
+            async () => await _gateway.RefundAsync(null!));
+
+        Assert.AreEqual("chargeId", ex.ParamName);
+    }
+
+    [TestMethod]
+    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
+    {
+        await Assert.ThrowsExactlyAsync<ArgumentException>(
+            async () => await _gateway.RefundAsync(string.Empty));
+    }
+
+    [TestMethod]
+    public async Task RefundAsync_NonExistentChargeId_ReturnsFailure()
+    {
+        var result = await _gateway.RefundAsync("ch_does_not_exist");
+
+        Assert.IsNotNull(result);
+        Assert.IsFalse(result.Success);
+    }
+
+    [TestMethod]
+    public async Task RefundAsync_DuplicateRefund_ReturnsFailure()
+    {
+        var charge = await _gateway.ChargeAsync("tok_valid_visa", 30m);
+        var firstRefund = await _gateway.RefundAsync(charge.ChargeId);
+        Assert.IsTrue(firstRefund.Success);
+
+        var secondRefund = await _gateway.RefundAsync(charge.ChargeId);
+        Assert.IsFalse(secondRefund.Success);
+    }
+}
